import copy
import hashlib
import json
from collections import Counter
from pathlib import Path

ROOT = Path('/workspace/scratch/4547408f28d5')
WORK = ROOT / 'scope_audit_v4'
OUT = ROOT / 'qwen-evidence-work/training_outputs'

def read(path):
    return json.loads(path.read_text())

def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def write(path, value):
    path.write_text(json.dumps(value,ensure_ascii=False,indent=2,allow_nan=False)+'\n')

previous_path = OUT / 'csts_development_blind_audit_v3_20261026.json'
previous = read(previous_path)
old = {r['row_id']:r for r in previous['labels']}
anchors = {'train_72':5,'train_7753':1,'train_8859':5}
initial, focused, input_rows = {}, {}, {}
receipts = []
for i in range(1,7):
    source = read(WORK/f'part{i}_inputs.json')
    reviews = read(WORK/f'part{i}_review.json')
    queue = read(WORK/f'part{i}_adjudication_inputs.json')
    decisions = read(WORK/f'part{i}_adjudicated.json')
    assert len(source)==len(reviews)==305
    assert [r['row_id'] for r in source]==[r['row_id'] for r in reviews]
    assert [r['row_id'] for r in queue]==[r['row_id'] for r in decisions]
    initial.update((r['row_id'],r) for r in reviews)
    focused.update((r['row_id'],r) for r in decisions)
    input_rows.update((r['row_id'],r) for r in source)
    receipts.append({'part':i,'rows':305,'flagged_cases':len(queue),'input_sha256':digest(WORK/f'part{i}_inputs.json'),'initial_review_sha256':digest(WORK/f'part{i}_review.json'),'focused_input_sha256':digest(WORK/f'part{i}_adjudication_inputs.json'),'focused_decision_sha256':digest(WORK/f'part{i}_adjudicated.json'),'validity_clarification_applied':True})
assert set(initial)==set(old)==set(input_rows) and len(initial)==1830
assert len(focused)==397
canonical_classes = read(WORK/'canonical_resolution_classes.json')
repair_case_ids = {r['row_id'] for r in read(WORK/'calibration_policy_repair_review.json') if r['classification']=='calibration_only'}
published_v4 = {r['row_id']:r for r in read(OUT/'csts_development_blind_audit_v4_20261026.json')['labels']}
root_overrides = {r['row_id']:r for r in read(WORK/'root_quality_decisions.json')}
final, transitions, calibration = [], [], []
for before in previous['labels']:
    rid=before['row_id']; first=initial[rid]
    row=copy.deepcopy(before)
    row['scope_review_version']=4.1
    row['scope_review_part']=next(i for i in range(1,7) if rid in {r['row_id'] for r in read(WORK/f'part{i}_inputs.json')})
    part=row['scope_review_part']
    row['historical_reviewer_ids']=copy.deepcopy(before.get('reviewer_ids',[]))
    row['reviewer_ids']=[f'scope_v4_part{part}']
    for field in ('scope','value_a','value_b'):
        row[field]=first[field]
    if rid in anchors:
        assert before['rating']==anchors[rid]
        row['scope_review_resolution']='user_anchor_preserved'
        row['reviewer_ids'].append('user_adjudication_v3')
    elif rid in focused:
        decision=focused[rid]
        reviewer={1:6,2:1,3:5,4:3,5:4,6:2}[part]
        row['reviewer_ids'].append(f'scope_v4_part{reviewer}')
        basis=str(decision['decision_basis']).lower()
        if canonical_classes[rid] == 'calibration_only' and before['status'] in {'agreement','adjudicated'} and decision['status']=='rated':
            calibration.append(rid)
            row['scope_review_resolution']='existing_defensible_grade_preserved'
        else:
            row['status']='adjudicated' if decision['status']=='rated' else decision['status']
            row['rating']=decision['rating']
            row['rationale']=decision['rationale']
            row['scope_review_resolution']='focused_semantic_adjudication'
            row['scope']=decision['scope']
            row['value_a']=decision['value_a'];row['value_b']=decision['value_b']
            if decision['status']=='excluded_ambiguous':
                assert len(decision.get('alternatives',[]))>=2
                row['scope_alternatives']=decision['alternatives']
    else:
        assert first['status']!='needs_scope'
        assert (before['status'] in {'agreement','adjudicated'})==(first['status']=='rated')
        assert before['rating']==first['rating']
        row['scope_review_resolution']='fresh_review_confirms_current_label'
    if rid in root_overrides:
        d=root_overrides[rid]
        row['status']='adjudicated' if d['status']=='rated' else d['status']
        row['rating']=d['rating'];row['rationale']=d['rationale']
        row['scope_review_resolution']='root_semantic_quality_check'
        row['reviewer_ids'].append('root_quality_review')
        for field in ('scope','value_a','value_b'):
            row[field]=d[field]
        row.pop('scope_alternatives',None)
    if rid in repair_case_ids:
        for field in ('scope','value_a','value_b'):
            row[field]=published_v4[rid][field]
    rated=row['status'] in {'agreement','adjudicated'}
    assert (row['rating'] in (1,2,3,4,5)) if rated else row['rating'] is None
    assert row['status'] in {'agreement','adjudicated','invalid','excluded_ambiguous'}
    old_rated=before['status'] in {'agreement','adjudicated'}
    if old_rated!=rated or before['rating']!=row['rating'] or (not rated and before['status']!=row['status']):
        row['previous_version3_decision']={k:before[k] for k in ('status','rating','rationale')}
        transitions.append({'row_id':rid,'previous_status':before['status'],'previous_rating':before['rating'],'current_status':row['status'],'current_rating':row['rating'],'resolution':row['scope_review_resolution'],'rationale':row['rationale']})
    final.append(row)

final_map={r['row_id']:r for r in final}
calibration=[rid for rid in calibration if final_map[rid]['rating']==old[rid]['rating']]

result=copy.deepcopy(previous)
result.update(audit_version=4.1,label_provenance='Scope-first assistant-model review of all development cases, focused semantic adjudication and root quality checks, with three user-adjudicated anchors.',previous_audit_sha256=digest(previous_path),labels=final,status_counts=dict(Counter(r['status'] for r in final)))
result['scope_review']={'rubric_sha256':digest(WORK/'rubric.md'),'resolution_policy':read(WORK/'resolution_policy.json'),'coverage':1830,'focused_cases':397,'part_receipts':receipts,'calibration_only_current_grades_preserved':calibration,'root_quality_decisions':list(root_overrides.values()),'transitions':transitions,'model_predictions_used_for_label_decisions':False,'previous_supplied_labels_used_for_fresh_reviews':False,'anchors':anchors,'all_dispositions_final':True,'pending_review':0}
result['calibration_policy_repair']={'previous_published_audit_sha256':digest(OUT/'csts_development_blind_audit_v4_20261026.json'),'previous_published_commit':'a9c8619fa332d4ed1f4c594135805cec8d5a561c','scope':'Restore the predeclared preservation policy for 22 calibration-only judgments; preserve four genuine corrections and explicit root exceptions.','decision_records':read(WORK/'calibration_policy_repair_review.json'),'canonical_resolution_classes':canonical_classes,'original_version4_performance_was_known':True,'per_comparison_encoder_predictions_used_for_repair_classification':False}
write(OUT/'csts_validation_audit_v4_1_20261027.json',result)
write(WORK/'final_transitions_v4_1.json',transitions)
print(json.dumps({'status_counts':result['status_counts'],'transitions':len(transitions),'calibration_preserved':len(calibration),'restored_from_exclusions':sum(t['previous_status'] in {'invalid','excluded_ambiguous'} and t['current_status'] in {'agreement','adjudicated'} for t in transitions),'newly_excluded':sum(t['previous_status'] in {'agreement','adjudicated'} and t['current_status'] in {'invalid','excluded_ambiguous'} for t in transitions),'numeric_rating_changes':sum(t['previous_rating'] is not None and t['current_rating'] is not None and t['previous_rating']!=t['current_rating'] for t in transitions),'formerly_ambiguous_restored':sum(t['previous_status']=='excluded_ambiguous' and t['current_status'] in {'agreement','adjudicated'} for t in transitions)},indent=2))
